ticket.description:
En tant que gestionnaire, je veux exporter une facture en PDF depuis la fiche client, pour l’envoyer sans passer par le module Comptabilité.

Critères d’acceptation :
- un bouton « Exporter en PDF » sur chaque facture ;
- le PDF reprend le logo et les mentions légales ;
- le nom du fichier suit le format FACT-2026-0142.pdf.

output.contenu:
import { genererPdf } from "../pdf";
import { numeroFacture } from "./numerotation";
import type { Facture } from "./types";

/** Exporte une facture en PDF, avec logo et mentions légales. */
export async function exporterFacture(facture: Facture): Promise<Blob> {
  const nom = `${numeroFacture(facture)}.pdf`;
  return genererPdf({
    nom,
    logo: "/assets/logo-acme.svg",
    lignes: facture.lignes.map((ligne) => ({
      libelle: ligne.libelle,
      quantite: ligne.quantite,
      prixUnitaire: ligne.prixUnitaire,
    })),
    mentions: facture.mentionsLegales,
  });
}

